def balance_dict(d, target_key, ratio=0.5):
    total = sum(d.values())
    new_values = {}

    for key, value in d.items():
        if key == target_key:
            new_values[key] = int(total * ratio)
        else:
            new_values[key] = int(value * (total / (1 - ratio)))

    return new_values

