```javascript
function switchAdjectives(sentence) {
  const words = sentence.split(" ");
  const adjectives = [];
  let i = 0;

  while (i < words.length) {
    if (words[i].match(/^(\w+)\s*(\w+)$/)) {
      adjectives.push(words[i]);
      i += 2;
    } else {
      i++;
    }
  }

  const newSentence = adjectives.join(" ") + " " + words[words.length - 1];
  return newSentence;
}

const input = "Beautiful green trees are in the park";
const output = switchAdjectives(input);
console.log(output); // Output: Green beautiful trees are in the park
```

