```javascript
function sortJsonObjectByKeys(jsonObj, keys) {
  const sortedObj = {};
  Object.keys(jsonObj).sort((a, b) => keys.indexOf(a) - keys.indexOf(b)).forEach(key => {
    sortedObj[key] = jsonObj[key];
  });
  return sortedObj;
}
```

To use this function, pass the JSON object and an array of keys you want to sort by:

```javascript
const jsonObj = {
  apple: 1,
  banana: 2,
  cherry: 3
};

const keys = ['apple', 'cherry'];

const sortedObj = sortJsonObjectByKeys(jsonObj, keys);
console.log(sortedObj); // Output: { apple: 1, cherry: 3 }
```

