// Function to generate the Fibonacci sequence
vector<int> fibonacci(int n, int a, int b) {
    if (n == 0) {
        return vector<int>();
    } else {
        vector<int> result = fibonacci(n - 1, b, a + b);
        result.push_back(a);
        return result;
    }
}

