Here's an example of a generic REST service wrapper class in C# that includes auth token handling:

```csharp
using System;
using System.Net.Http;
using System.Threading.Tasks;
using Newtonsoft.Json;
using System.Security.Claims;
using Microsoft.IdentityModel.Tokens;
using System.IdentityModel.Tokens.Jwt;

public class RestServiceWrapper<T>
{
    private readonly HttpClient _httpClient;
    private readonly string _apiUrl;
    private readonly string _authToken;

    public RestServiceWrapper(string apiUrl, string authToken)
    {
        _httpClient = new HttpClient();
        _apiUrl = apiUrl;
        _authToken = authToken;
    }

    public async Task<T> GetAsync()
    {
        var requestMessage = new HttpRequestMessage(HttpMethod.Get, $"{_apiUrl}/");

        // Add the authorization header
        requestMessage.Headers.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", _authToken);

        var response = await _httpClient.SendAsync(requestMessage);
        response.EnsureSuccessStatusCode();

        return await response.Content.ReadAsAsync<T>();
    }
}

// Example usage
var apiUrl = "https://example.com/api";
var authToken = "your_auth_token_here";

var restServiceWrapper = new RestServiceWrapper<dynamic>(apiUrl, authToken);

var result = await restServiceWrapper.GetAsync();
Console.WriteLine(result);
```

Replace `"your_auth_token_here"` with your actual authentication token. This example uses the `HttpClient` class to make a GET request to the specified API URL. The `Authorization` header is set to include the authentication token.

