Here's a simple Go program that parses a struct in a Go source file and generates an Avro schema from it:

```go
package main

import (
	"fmt"
	"os"
	"reflect"
	"strings"
)

func main() {
	if len(os.Args) != 3 {
		fmt.Println("Usage: ./parse_struct <source_file> <struct_name>")
		os.Exit(1)
	}

	sourceFile := os.Args[1]
	structName := os.Args[2]

	content, err := os.ReadFile(sourceFile)
	if err != nil {
		fmt.Println("Error reading source file:", err)
		os.Exit(1)
	}

	tokens := strings.Split(string(content), "\n")
	for _, token := range tokens {
		if token == "type" {
			structType := reflect.TypeOf(reflect.ValueOf(token).Interface())
			if structType.Kind() == reflect.Struct {
				generateAvroSchema(structType, structName)
			}
		}
	}
}

func generateAvroSchema(structType reflect.Type, structName string) {
	schema := fmt.Sprintf("{%s}", structName)
	for i := 0; i < structType.NumField(); i++ {
		field := structType.Field(i)
		if field.Anonymous {
			generateAvroSchema(field.Type, field.Name)
		} else {
			schema += fmt.Sprintf(", %s: %s", field.Name, field.Type.String())
		}
	}
	schema += "}"

	err := os.WriteFile("struct.avsc", []byte(schema), 0644)
	if err != nil {
		fmt.Println("Error writing Avro schema:", err)
		os.Exit(1)
	}
}
```

