To retrieve the username from the JWT token in ASP.NET Core Web API, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package if you haven't already. You can do this by running the following command in the Package Manager Console:

```
Install-Package Microsoft.IdentityModel.Tokens
```

2. In your WebAPI project, create a new class that will be responsible for handling the JWT token and retrieving the username. For example:

```csharp
using System;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Claims;
using System.Text;
using Microsoft.IdentityModel.Tokens;

public class JwtService
{
    private readonly string _jwtKey;

    public JwtService(string jwtKey)
    {
        _jwtKey = jwtKey;
    }

    public string GetUsernameFromToken(string token)
    {
        var tokenHandler = new JwtSecurityTokenHandler();
        var key = Encoding.ASCII.Parse(_jwtKey);
        var tokenValidationParameters = new TokenValidationParameters
        {
            IssuerSigningKey = key,
            ValidateIssuer = false,
            ValidateAudience = false,
            ValidateLifetime = true,
            ClockSkew = TimeSpan.Zero
        };

        var securityToken = tokenHandler.ReadJwtToken(token, tokenValidationParameters);
        var claims = securityToken.Claims;

        foreach (var claim in claims)
        {
            if (claim.Type == "http://schemas.microsoft.com/identity/claims/username")
            {
                return claim.Value;
            }
        }

        return null;
    }
}
```

3. In your Startup.cs file, add the JwtService to the services collection:

```csharp
public void ConfigureServices(IServiceCollection services)
{
    // ...

    services.AddSingleton<JwtService>();
}
```

4. Now, you can use the JwtService to retrieve the username from the JWT token in your controllers or other parts

