Here's a simple C function that converts an array of command-line arguments (`argv`) to a null-terminated string:

```c
#include <stdio.h>
#include <stdlib.h>

char *convert_argv_to_cstring(int argc, char **argv) {
    size_t len = 0;
    for (int i = 0; i < argc; ++i) {
        len += strlen(argv[i]) + 1; // Add 1 for the null terminator
    }

    char *str = malloc(len);
    if (!str) {
        return NULL;
    }

    for (int i = 0; i < argc; ++i) {
        strncat(str, argv[i], strlen(argv[i]));
        strncat(str, " ", 1); // Add a space separator
    }

    str[len - 1] = '\0'; // Ensure the string is null-terminated
    return str;
}

int main() {
    int argc = 3;
    char **argv = {"arg1", "arg2", "arg3"};

    char *cstr = convert_argv_to_cstring(argc, argv);
    if (cstr) {
        printf("Converted argv to cstring: %s\n", cstr);
        free(cstr);
    } else {
        printf("Error allocating memory\n");
    }

    return 0;
}
```

