```php
function getLoyalCustomers($conn, $productName, $frequency) {
    $query = "SELECT c.name, c.email, COUNT(p.id) AS purchase_count
              FROM customers c
              JOIN purchases p ON c.id = p.customer_id
              WHERE p.product_name = :product_name AND p.date BETWEEN DATE_SUB(CURDATE(), INTERVAL 1 WEEK) AND CURDATE()
              GROUP BY c.id
              HAVING purchase_count >= :frequency";

    $stmt = $conn->prepare($query);
    $stmt->bindParam(':product_name', $productName);
    $stmt->bindParam(':frequency', $frequency);
    $stmt->execute();

    return $stmt->fetchAll(PDO::FETCH_ASSOC);
}
