Here's a simple decorator for Nest.js middleware that checks the `NODE_ENV` variable and returns `false` if it's not set to 'true'. If the environment is set to 'true', it calls the next middleware function.

```typescript
import { createParamDecorator, ExecutionContext } from '@nestjs/common';

export const IsDevModeEnabled = createParamDecorator(
  (data: unknown, ctx: ExecutionContext) => {
    const request = ctx.switchToHttp().getRequest();
    return request.app.get('env') === 'development';
  },
);

export function DevModeMiddleware(
  condition?: boolean,
): ParameterDecorator | MiddlewareFunction {
  return (target: Object, propertyKey: string) => {
    if (condition === false) {
      throw new Error('DevModeMiddleware can only be used in development mode.');
    }

    Reflect.defineMetadata('isDevModeEnabled', true, target, propertyKey);
  };
}
```

To use this decorator, you can apply it to a method or class like this:

```typescript
@IsDevModeEnabled()
class MyController {
  @DevModeMiddleware()
  async getHello() {
    // This middleware will only run in development mode
    console.log('Hello from dev mode!');
  }
}
```

In the example above, the `getHello` method will only be called when the `NODE_ENV` variable is set to 'development'. If the environment is set to 'production', the method will not be executed.

