Here's a simple example of a toast notification using React Context:

```jsx
import React, { createContext, useEffect, useState } from 'react';

const ToastContext = createContext();

function ToastProvider(props) {
  const [toasts, setToasts] = useState([]);

  useEffect(() => {
    const timer = setTimeout(() => {
      setToasts([]);
    }, 3000);

    return () => clearTimeout(timer);
  }, [toasts]);

  function addToast(message) {
    setToasts((prevToasts) => [...prevToasts, message]);
  }

  return (
    <ToastContext.Provider value={{ toasts, addToast }}>
      {props.children}
    </ToastContext.Provider>
  );
}

function ToastConsumer() {
  const { toasts, addToast } = React.useContext(ToastContext);

  function handleClick() {
    addToast('This is a toast notification.');
  }

  return (
    <div>
      <button onClick={handleClick}>Show Toast</button>
      {toasts.map((toast) => (
        <div key={toast}>{toast}</div>
      ))}
    </div>
  );
}

export default function App() {
  return (
    <ToastProvider>
      <ToastConsumer />
    </ToastProvider>
  );
}
```

