Here's a Go program that identifies if a given sentence contains a double negative:

```go
package main

import (
	"fmt"
	"strings"
)

func isDoubleNegative(sentence string) bool {
	negativeWords := []string{"not", "never", "no", "none", "nothing"}

	words := strings.Split(sentence, " ")
	for _, word := range words {
		if containsNegativeWord(word) && containsNotBeforeNegativeWord(word, sentences) {
			return true
		}
	}

	return false
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if word == negativeWord {
			return true
		}
	}

	return false
}

func containsNotBeforeNegativeWord(word string, sentences []string) bool {
	for _, sentence := range sentences {
		if strings.HasPrefix(sentence, word) && containsNegativeWord(sentences[i]) {
			return true
		}
	}

	return false
}

func main() {
	sentence := "He isn't not worried about the coronavirus situation"
	if isDoubleNegative(sentence) {
		fmt.Println("The sentence contains a double negative.")
	} else {
		fmt.Println("The sentence does not contain a double negative.")
	}
}
```

