        }
        if ($_.GetAccessRuleSidHistory()) {
            $subfolders = Get-ChildItem -Path $folderPath -Directory | ForEach-Object {
                CheckFolderACLs($_.FullName)
            }
        }
    }
}

# Start the search
CheckFolderACLs($startPath)
```

Replace `"your_domain_name"` with the name of your domain, and `"C:\path\to\start\search"` with the path where you want to start the search. This script will check the ACLs of the specified folder and its subfolders, and print out any folders that have ACL references to SIDs in the SIDHistory of users
